<script setup lang="ts">import type {Workbench} from '../app/useWorkbench';import PathField from '../shared/PathField.vue';import JsonReport from '../shared/JsonReport.vue';const {w}=defineProps<{w:Workbench}>();const s=w.s;const kindLabels:Record<string,string>={engine:'引擎项目',map:'地图', 'map-root':'地图根目录',task:'工参任务','task-root':'工参根目录',config:'配置资源',dll:'动态库',runtime:'运行 XML'};</script>
<template><section class="card" data-testid="discovery"><div class="card-heading"><span class="card-icon">⌕</span><div><h2>发现本机资源</h2><p>仅检查所选范围的文件内容，不运行发现的程序或脚本</p></div></div><div class="scan-form"><PathField v-model="s.scanRoot" label="搜索范围"/><label class="field"><span>最大深度</span><el-input-number v-model="s.scanDepth" :min="1" :max="12"/></label><label class="field"><span>文件数量上限</span><el-input-number v-model="s.scanBudget" :min="100" :max="100000" :step="5000"/></label><el-button type="primary" plain @click="w.startDiscovery" :disabled="!s.scanRoot||s.scan?.status==='running'">开始发现</el-button><el-button v-if="s.scan?.status==='running'" @click="w.cancelDiscovery">取消</el-button></div><template v-if="s.scan"><div class="scan-status"><i :class="s.scan.status==='running'?'spinner':'check-circle'"/><strong>{{s.scan.status==='running'?'正在检查目录':s.scan.status==='cancelled'?'扫描已取消，已保留部分结果':s.scan.status==='failed'?'扫描失败':'资源发现完成'}}</strong><span>已检查 {{s.scan.visited}} 项 · 发现 {{s.scan.results?.length||0}} 项</span><el-tag v-if="s.scan.limited" type="warning">已达范围上限</el-tag></div><el-table :data="s.scan.results||[]" max-height="330" empty-text="当前范围未发现候选，请换一个目录或手动指定路径"><el-table-column label="类型" width="120"><template #default="{row}"><el-tag effect="plain">{{kindLabels[row.kind]||row.kind}}</el-tag></template></el-table-column><el-table-column label="资源与识别依据" min-width="250"><template #default="{row}"><strong>{{row.label}}</strong><code class="table-path">{{row.path}}</code><small>{{row.evidence?.join(' · ')}}</small></template></el-table-column><el-table-column width="110"><template #default="{row}"><el-button size="small" @click="w.useCandidate(row)">填入草稿</el-button></template></el-table-column></el-table><JsonReport v-if="s.scan.skipped?.length" :data="s.scan.skipped" title="查看跳过目录与原因"/></template></section></template>
